          size="sm"
          onClick={onSeed}
          disabled={isPending}
        >
          <Sparkles className="size-4" aria-hidden />
          Seed 12 exemples
        </Button>
        <Button type="button" size="sm" onClick={onCreate} disabled={isPending}>
          <Plus className="size-4" aria-hidden />
          Nouveau tag
        </Button>
      </div>
    </div>
  );
}

