import { Suspense } from "react";
import Link from "next/link";
import Image from "next/image";
import { connection } from "next/server";
import {
  ArrowRight,
  ChefHat,
  Clock,
  Flame,
  FolderTree,
  Sparkles,
  Tag as TagIcon,
  UtensilsCrossed,
} from "lucide-react";

import { prisma } from "@/lib/prisma";
import { DIFFICULTY_LABELS } from "@/lib/labels";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

/* ------------------------------------------------------------------ */
/*  Types locaux                                                       */
/* ------------------------------------------------------------------ */

interface RecipeCardData {
  readonly id: string;
  readonly slugRecipe: string;
  readonly title: string;
  readonly description: string;
  readonly image: string | null;
  readonly prepTime: number;
  readonly cookTime: number;
  readonly servings: number;
  readonly difficulty: "EASY" | "MEDIUM" | "HARD";
}

interface CategoryCardData {
  readonly id: string;
  readonly name: string;
  readonly image: string | null;
  readonly recipeCount: number;
}

interface TagCardData {
  readonly id: string;
  readonly name: string;
  readonly recipeCount: number;
}

/* ------------------------------------------------------------------ */
/*  Helpers purs                                                       */
/* ------------------------------------------------------------------ */

function formatMinutes(minutes: number): string {
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return rest === 0 ? `${hours} h` : `${hours} h ${rest}`;
}

function totalTime(prepTime: number, cookTime: number): string {
  return formatMinutes(prepTime + cookTime);
}

/* ------------------------------------------------------------------ */
/*  Page                                                               */
/* ------------------------------------------------------------------ */

export default function HomePage() {
  return (
    <div className="mx-auto w-full max-w-7xl px-4 pb-16 pt-8 sm:px-6 sm:pt-10 lg:px-8">
      <Suspense fallback={<HomeSkeleton />}>
        <HomeContent />
      </Suspense>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Contenu dynamique                                                  */
/* ------------------------------------------------------------------ */

async function HomeContent() {
  // Frontière runtime explicite — requise par cacheComponents: true.
  // Sans cet appel, Next.js tente un pré-rendu au build et bloque sur
  // les accès Prisma qui utilisent Date en interne (new Date()).
  await connection();

  const [featured, popular, categories, tags] = await Promise.all([
    prisma.recipe.findFirst({
      orderBy: { displayOrder: "asc" },
      select: {
        id: true,
        slugRecipe: true,
        title: true,
        description: true,
        image: true,
        prepTime: true,
        cookTime: true,
        servings: true,
        difficulty: true,
      },
    }),
    prisma.recipe.findMany({
      orderBy: { displayOrder: "asc" },
      skip: 1,
      take: 8,
      select: {
        id: true,
        slugRecipe: true,
        title: true,
        description: true,
        image: true,
        prepTime: true,
        cookTime: true,
        servings: true,
        difficulty: true,
      },
    }),
    prisma.category.findMany({
      orderBy: { name: "asc" },
      include: {
        _count: { select: { recipes: true } },
      },
    }),
    prisma.tag.findMany({
      orderBy: [{ recipes: { _count: "desc" } }, { name: "asc" }],
      take: 16,
      include: {
        _count: { select: { recipes: true } },
      },
    }),
  ]);

  const isEmpty =
    !featured && popular.length === 0 && categories.length === 0;

  if (isEmpty) {
    return <EmptyHome />;
  }

  const categoryData: CategoryCardData[] = categories.map((category) => ({
    id: category.id,
    name: category.name,
    image: category.image,
    recipeCount: category._count.recipes,
  }));

  const tagData: TagCardData[] = tags
    .filter((tag) => tag._count.recipes > 0)
    .map((tag) => ({
      id: tag.id,
      name: tag.name,
      recipeCount: tag._count.recipes,
    }));

  return (
    <div className="space-y-16">
      {featured && <Hero recipe={featured} />}
      {popular.length > 0 && <RecipeGrid recipes={popular} />}
      {categoryData.length > 0 && <CategoryGrid categories={categoryData} />}
      {tagData.length > 0 && <TagCloud tags={tagData} />}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Hero                                                               */
/* ------------------------------------------------------------------ */

function Hero({ recipe }: { readonly recipe: RecipeCardData }) {
  return (
    <section
      aria-labelledby="hero-title"
      className="grid items-center gap-8 lg:grid-cols-2 lg:gap-12"
    >
      {/* Texte */}
      <div className="order-2 space-y-5 lg:order-1">
        <Badge variant="secondary" className="gap-1.5">
          <Sparkles className="size-3" aria-hidden />
          À la une
        </Badge>

        <div className="space-y-3">
          <h1
            id="hero-title"
            className="text-3xl font-bold tracking-tight text-foreground sm:text-4xl lg:text-5xl"
          >
            {recipe.title}
          </h1>
          <p className="max-w-xl text-base leading-relaxed text-muted-foreground sm:text-lg">
            {recipe.description}
          </p>
        </div>

        {/* Méta */}
        <div className="flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-muted-foreground">
          <span className="inline-flex items-center gap-1.5">
            <Clock className="size-4" aria-hidden />
            {totalTime(recipe.prepTime, recipe.cookTime)}
          </span>
          <span className="inline-flex items-center gap-1.5">
            <ChefHat className="size-4" aria-hidden />
            {recipe.servings} pers.
          </span>
          <span className="inline-flex items-center gap-1.5">
            <Flame className="size-4" aria-hidden />
            {DIFFICULTY_LABELS[recipe.difficulty]}
          </span>
        </div>

        {/* CTA */}
        <div className="flex flex-wrap gap-3 pt-2">
          <Button
            nativeButton={false}
            render={<Link href={`/recipes/${recipe.slugRecipe}`} />}
          >
            Voir la recette
            <ArrowRight className="size-4" aria-hidden />
          </Button>
          <Button
            variant="outline"
            nativeButton={false}
            render={<Link href="/recipes" />}
          >
            <UtensilsCrossed className="size-4" aria-hidden />
            Toutes les recettes
          </Button>
        </div>
      </div>

      {/* Image */}
      <div className="order-1 aspect-[4/3] overflow-hidden rounded-2xl border border-border/60 bg-muted lg:order-2">
        {recipe.image ? (
          <Image
            src={recipe.image}
            alt={recipe.title}
            width={1200}
            height={900}
            priority
            sizes="(max-width: 1024px) 100vw, 50vw"
            className="size-full object-cover transition-transform duration-500 hover:scale-[1.02]"
          />
        ) : (
          <div className="grid size-full place-items-center bg-gradient-to-br from-chart-1/10 via-chart-2/10 to-chart-5/10">
            <ChefHat className="size-16 text-muted-foreground" aria-hidden />
          </div>
        )}
      </div>
    </section>
  );
}

/* ------------------------------------------------------------------ */
/*  Grille recettes                                                    */
/* ------------------------------------------------------------------ */

function RecipeGrid({
  recipes,
}: {
  readonly recipes: readonly RecipeCardData[];
}) {
  return (
    <section aria-labelledby="recipes-title" className="space-y-6">
      <header className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2
            id="recipes-title"
            className="text-2xl font-bold tracking-tight text-foreground sm:text-3xl"
          >
            Recettes du moment
          </h2>
          <p className="mt-1 text-sm text-muted-foreground">
            Une sélection pour vous inspirer aujourd&apos;hui.
          </p>
        </div>
        <Link
          href="/recipes"
          className="inline-flex items-center gap-1 text-sm font-medium text-foreground underline-offset-4 hover:underline"
        >
          Tout voir
          <ArrowRight className="size-3.5" aria-hidden />
        </Link>
      </header>

      <ul className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
        {recipes.map((recipe) => (
          <li key={recipe.id}>
            <RecipeCard recipe={recipe} />
          </li>
        ))}
      </ul>
